FROM T_USER
WHERE ID = #{id}

SELECT COUNT(*) > 0 AS `EXISTS`
FROM T_USER
WHERE EMAIL = #{email}

SELECT ID, NAME, PASSWORD, PASSWORD_SALT
FROM T_USER
WHERE ID = #{id}

SELECT ID, NAME, EMAIL, PHONE, ADDRESS, ADDRESS_DETAIL, POSTCODE, ACCOUNT_TYPE, BIRTH_DATE, GENDER, GUARDIAN_NAME, GUARDIAN_PHONE, ONBOARDING_COMPLETED, UNIX_TIMESTAMP(CREATED_AT) * 1000 CREATED_AT, UNIX_TIMESTAMP(UPDATED_AT) * 1000 UPDATED_AT
FROM T_USER
WHERE ID = #{id}

mapper.update:
UPDATE T_USER
PHONE = #{phone}, ADDRESS = #{address}, ADDRESS_DETAIL = #{addressDetail}, POSTCODE = #{postcode},
WHERE ID = #{id}

mapper.select:
SELECT ID, NAME, EMAIL
FROM T_USER
WHERE NAME = #{name}
  AND EMAIL = #{email}

  AND ID = #{id}

mapper.update:
UPDATE T_USER
SET PASSWORD = #{password}, PASSWORD_SALT = #{passwordSalt}
